    explicit integral_constructor(const value_t target_type = value_t::number_integer,
                                  const bool release_storage = true) noexcept
        : m_target_type(target_type)
        , m_release_storage(release_storage)
    {}

    template<typename NumberType>
    void construct(BasicJsonType& j, const NumberType val) noexcept
    {
        auto& data = j.m_data;
        auto& value = data.m_value;
        const auto current_type = data.m_type;

        if (m_release_storage)
        {
            bool owns_storage = false;
            switch (current_type)
            {
                case value_t::object:
                {
                    owns_storage = value.object != nullptr;
                    break;
                }

                case value_t::array:
                {
                    owns_storage = value.array != nullptr;
                    break;
                }

                case value_t::string:
                {
                    owns_storage = value.string != nullptr;
                    break;
                }

                case value_t::binary:
                {
                    owns_storage = value.binary != nullptr;
                    if (owns_storage && value.binary->has_subtype())
                    {
                        value.binary->clear_subtype();
                    }
                    break;
                }

                case value_t::null:
                case value_t::boolean:
                case value_t::number_integer:
                case value_t::number_unsigned:
                case value_t::number_float:
                case value_t::discarded:
                default:
                {
                    break;
                }
            }

            if (owns_storage)
            {
                value.destroy(current_type);
            }
        }

        data.m_type = m_target_type;
        if (m_target_type == value_t::number_unsigned)
        {
            value = static_cast<typename BasicJsonType::number_unsigned_t>(val);
        }
        else
        {
            value = static_cast<typename BasicJsonType::number_integer_t>(val);
        }
        j.assert_invariant();
    }
};

